    FILTER(xsd:decimal(?temp_value) < 0)
    FILTER(?time >= "2000-01-01T00:00:00"^^xsd:dateTime && ?time < "2011-01-01T00:00:00"^^xsd:dateTime)
    BIND(xsd:date(?time) AS ?day)
